const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Monte Pisano area)
    const center = ee.Geometry.Point([10.45, 43.79]);
    const halfWidthDeg = 0.14; // ~11 km E/W at this latitude
    const halfHeightDeg = 0.08; // ~9 km N/S
    const region = ee.Geometry.Rectangle([10.45 - halfWidthDeg, 43.79 - halfHeightDeg, 10.45 + halfWidthDeg, 43.79 + halfHeightDeg], null, false);
    const midLon = 10.45;
    const eastGeom = ee.Geometry.Rectangle([midLon, 43.79 - halfHeightDeg, 10.45 + halfWidthDeg, 43.79 + halfHeightDeg], null, false);
    const westGeom = ee.Geometry.Rectangle([10.45 - halfWidthDeg, 43.79 - halfHeightDeg, midLon, 43.79 + halfHeightDeg], null, false);

    // Date windows
    const primaryStart = '2019-02-25';
    const primaryEnd = '2019-02-26';
    const fallbackStart = '2019-02-24';
    const fallbackEnd = '2019-02-27';

    // Helper to pick image from a collection
    function pickImage(col) {
      return ee.Image(col.sort('CLOUD_COVER').first());
    }

    // Try L2 SR first (preferred)
    let colSR = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(region).filterDate(primaryStart, primaryEnd);
    let sizeSR = colSR.size().getInfo();
    // Fallback TOA if SR empty
    let colTOA = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA').filterBounds(region).filterDate(primaryStart, primaryEnd);
    let sizeTOA = colTOA.size().getInfo();

    if (sizeSR === 0 && sizeTOA === 0) {
      // Widen date window
      colSR = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(region).filterDate(fallbackStart, fallbackEnd);
      sizeSR = colSR.size().getInfo();
      colTOA = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA').filterBounds(region).filterDate(fallbackStart, fallbackEnd);
      sizeTOA = colTOA.size().getInfo();
    }

    console.log(`Window: ${primaryStart}→${primaryEnd} (fallback ${fallbackStart}→${fallbackEnd})`);
    console.log(`L8 L2 SR images: ${sizeSR} | L8 TOA images: ${sizeTOA}`);

    if (sizeSR === 0 && sizeTOA === 0) {
      console.log('No images found for date/location.');
      console.log('C1');
      return;
    }

    // Choose image and scale/rename bands consistently
    let img, scaled, isSR = false;
    if (sizeSR > 0) {
      img = pickImage(colSR);
      const optical = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
                         .multiply(0.0000275).add(-0.2)
                         .rename(['blue','green','red','nir','swir1','swir2']);
      scaled = optical;
      isSR = true;
    } else {
      img = pickImage(colTOA);
      // TOA reflectance bands already scaled 0-1
      scaled = img.select(['B2','B3','B4','B5','B6','B7']).rename(['blue','green','red','nir','swir1','swir2']);
    }

    const imgId = (img.get('LANDSAT_PRODUCT_ID').getInfo()) || (img.get('system:index').getInfo());
    const whenUTC = img.date().format('YYYY-MM-dd HH:mm').getInfo();
    const cloudCover = img.get('CLOUD_COVER').getInfo();
    console.log(`Selected: ${imgId} @ ${whenUTC}Z | CloudCover(meta): ${cloudCover !== null ? cloudCover.toFixed(1) : 'NA'}%`);

    // 3. Processing
    const smokeIdx = scaled.normalizedDifference(['blue', 'swir2']).rename('smoke');
    const smokeFlag = scaled.select('blue').gt(0.08).and(scaled.select('swir2').lt(0.05)).and(scaled.select('red').gt(0.05)).rename('smoke').uint8();

    const reduceArgsEast = {reducer: ee.Reducer.count(), geometry: eastGeom, scale: 1000, maxPixels: 1e9, bestEffort: true};
    const reduceArgsWest = {reducer: ee.Reducer.count(), geometry: westGeom, scale: 1000, maxPixels: 1e9, bestEffort: true};

    const eastCountDict = scaled.select('blue').reduceRegion(reduceArgsEast).getInfo();
    const westCountDict = scaled.select('blue').reduceRegion(reduceArgsWest).getInfo();
    const eastCount = eastCountDict ? eastCountDict.blue : null;
    const westCount = westCountDict ? westCountDict.blue : null;

    if ((eastCount === null || eastCount === 0) && (westCount === null || westCount === 0)) {
      console.log('Valid pixels after processing: East 0, West 0.');
      console.log('C2');
      return;
    }

    const pReducer = ee.Reducer.percentile([95]);
    const eastBlueP = scaled.select('blue').reduceRegion({reducer: pReducer, geometry: eastGeom, scale: 1000, maxPixels: 1e9, bestEffort: true}).getInfo();
    const westBlueP = scaled.select('blue').reduceRegion({reducer: pReducer, geometry: westGeom, scale: 1000, maxPixels: 1e9, bestEffort: true}).getInfo();
    const eastBlueP95 = eastBlueP ? (eastBlueP.blue_p95 ?? eastBlueP['blue_p95']) : null;
    const westBlueP95 = westBlueP ? (westBlueP.blue_p95 ?? westBlueP['blue_p95']) : null;

    const eastSmokeSum = smokeFlag.reduceRegion({reducer: ee.Reducer.sum(), geometry: eastGeom, scale: 1000, maxPixels: 1e9, bestEffort: true}).getInfo();
    const westSmokeSum = smokeFlag.reduceRegion({reducer: ee.Reducer.sum(), geometry: westGeom, scale: 1000, maxPixels: 1e9, bestEffort: true}).getInfo();
    const eastSmokeCount = eastSmokeSum ? (eastSmokeSum.smoke || 0) : 0;
    const westSmokeCount = westSmokeSum ? (westSmokeSum.smoke || 0) : 0;

    // Validation for invalid stats
    const anyInvalid = [eastCount, westCount, eastBlueP95, westBlueP95, eastSmokeCount, westSmokeCount]
      .some(v => v === null || Number.isNaN(v));
    if (anyInvalid) {
      console.log('Calculation produced null/NaN.');
      console.log('C3');
      return;
    }

    console.log(`Valid px (1km): East ${eastCount}, West ${westCount}`);
    console.log(`Blue P95: East ${eastBlueP95.toFixed(3)}, West ${westBlueP95.toFixed(3)}`);
    console.log(`SmokePix (Blue>0.08 & SWIR2<0.05 & Red>0.05): East ${eastSmokeCount}, West ${westSmokeCount}`);

    const ratio = eastSmokeCount / Math.max(1, westSmokeCount);
    console.log(`East/West SmokePix ratio: ${ratio.toFixed(2)}`);

    // 5. Decision: smoke plume moving east if East>>West
    const eastDominant = (eastSmokeCount >= westSmokeCount * 1.5 && eastSmokeCount >= 5) ||
                         ((eastBlueP95 - westBlueP95) >= 0.02 && eastBlueP95 >= westBlueP95 * 1.25);
    if (eastDominant) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
